`eval()` を使わず、AST を利用して安全に計算できます。`+`, `-`, `*`, `/` と括弧、単項の負号に対応しています。

```python
import ast
import operator


def eval_expression(expr: str):
    tree = ast.parse(expr, mode="eval")

    binary_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
    }

    unary_operators = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    def evaluate(node):
        # 数値リテラル
        if isinstance(node, ast.Constant):
            if type(node.value) in (int, float):
                return node.value
            raise ValueError("数値以外は使用できません")

        # 単項演算子: -3, +3
        if isinstance(node, ast.UnaryOp):
            op = unary_operators.get(type(node.op))
            if op is None:
                raise ValueError("対応していない単項演算子です")
            return op(evaluate(node.operand))

        # 二項演算子
        if isinstance(node, ast.BinOp):
            op = binary_operators.get(type(node.op))
            if op is None:
                raise ValueError("対応していない演算子です")

            left = evaluate(node.left)
            right = evaluate(node.right)

            if isinstance(node.op, ast.Div) and right == 0:
                raise ZeroDivisionError("division by zero")

            return op(left, right)

        raise ValueError("不正な式です")

    return evaluate(tree.body)
```

使用例:

```python
print(eval_expression("3 + 4 * (2 - 1)"))  # 7
print(eval_expression("-2 * (3 + 4)"))      # -14
print(eval_expression("10 / 4"))            # 2.5

try:
    eval_expression("1 / 0")
except ZeroDivisionError:
    print("ゼロでは割れません")
```

演算子の優先順位は Python の規則に従うため、`*` と `/` が `+` と `-` より先に計算されます。

